create table public.draft_sessions(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.seasons(id) on delete cascade,status text not null check(status in('NOT_STARTED','ACTIVE','PAUSED','COMPLETED')),rounds integer not null check(rounds>0),allow_incomplete_keepers boolean not null default false,created_at timestamptz not null default now());
create table public.draft_events(id uuid primary key,session_id uuid not null references public.draft_sessions(id) on delete cascade,season_id uuid not null references public.seasons(id) on delete cascade,sequence bigint not null check(sequence>0),event_type text not null check(event_type in('DRAFT_STARTED','PICK_MADE','PICK_UNDONE','PICK_EDITED','DRAFT_PAUSED','DRAFT_RESUMED','DRAFT_COMPLETED')),occurred_at timestamptz not null,device_id text not null,payload jsonb not null default '{}',reverses_event_id uuid references public.draft_events(id),supersedes_event_id uuid references public.draft_events(id),unique(session_id,sequence));create index draft_events_session_sequence on public.draft_events(session_id,sequence);
create table public.draft_snapshots(session_id uuid primary key references public.draft_sessions(id) on delete cascade,season_id uuid not null references public.seasons(id) on delete cascade,event_sequence bigint not null,state_version integer not null,projection jsonb not null,created_at timestamptz not null default now());
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['draft_sessions','draft_events','draft_snapshots'] LOOP EXECUTE format('alter table public.%I enable row level security',t);EXECUTE format('create policy "private owner %1$s" on public.%1$I for all to authenticated using(exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id join public.draft_allowed_users a on a.user_id=auth.uid() where s.id=season_id and l.owner_id=auth.uid())) with check(exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id join public.draft_allowed_users a on a.user_id=auth.uid() where s.id=season_id and l.owner_id=auth.uid()))',t);END LOOP;END$$;
